import math
from functools import lru_cache

def count_binary_seq(n):
    @lru_cache(None)
    def helper(pos, ones_left, zeros_left):
        # Base case: if we have completed the sequence
        if pos == 2 * n:
            return 1 if ones_left == 0 and zeros_left == 0 else 0

        # If we exceed the allowed number of ones or zeros, return 0
        if ones_left < 0 or zeros_left < 0:
            return 0

        # Choose to add a '1' or a '0' to the sequence
        if pos < n:  # First half
            return helper(pos + 1, ones_left - 1, zeros_left) + helper(pos + 1, ones_left, zeros_left - 1)
        else:  # Second half
            return helper(pos + 1, ones_left - 1, zeros_left) + helper(pos + 1, ones_left, zeros_left - 1)

    # The total number of ones and zeros are equal to n
    return helper(0, n, n)

# Example usage and test
assert math.isclose(count_binary_seq(1), 2.0, rel_tol=0.001)
assert math.isclose(count_binary_seq(2), 6.0, rel_tol=0.001)
assert math.isclose(count_binary_seq(3), 20.0, rel_tol=0.001)
