def tuple_to_dict(input_tuple):
    """
    Converts a given tuple into a dictionary where adjacent elements form key-value pairs.

    Args:
    input_tuple (tuple): The input tuple with elements to be converted.

    Returns:
    dict: A dictionary with adjacent elements of the tuple as key-value pairs.
    """
    # Use dictionary comprehension to pair adjacent elements
    return {input_tuple[i]: input_tuple[i + 1] for i in range(0, len(input_tuple) - 1, 2)}

# Test cases
assert tuple_to_dict((1, 5, 7, 10, 13, 5)) == {1: 5, 7: 10, 13: 5}
assert tuple_to_dict((2, 4, 6, 8)) == {2: 4, 6: 8}
assert tuple_to_dict((9, 3)) == {9: 3}
assert tuple_to_dict(()) == {}
